// Precedence: Unary > Multiplicative > Additive > Shift > Comparison > Assignment

// 1. Precedence: Multiplicative (*) higher than Additive (+)
int a = 5, b = 2, c = 3;
int val_P = a + b * c;  // Evaluates as: a + (b * c) = 11

// Use parentheses to override default precedence
int val_O = (a + b) * c; // Evaluates as: (a + b) * c = 21

// 2. Associativity: Left-to-Right (L->R)
int L_R = 10 - 5 + 1;   // Evaluates as: (10 - 5) + 1 = 6

// 3. Associativity: Right-to-Left (R->L)
// Assignment operator (=)
int x, y, z;
x = y = z = 100;        // Evaluates as: x = (y = (z = 100));

// Conditional operator (? :) is R->L
int cond = 1 ? 2 : 3 ? 4 : 5; // Evaluates as: 1 ? 2 : (3 ? 4 : 5) = 2
